using NetArchTest.Rules;

namespace PaymentAuthorization.IntegrationTest.Architecture;

/// <summary>
/// Guards the Clean Architecture layering so a technical detail (I/O, HTTP client,
/// file system, framework type, ...) can never be reached for directly from Domain or
/// Application. Violations fail the build instead of surfacing in review.
/// </summary>
public sealed class LayerDependencyTests
{
    private const string DomainNamespace = "PaymentAuthorization.Domain";
    private const string ApplicationNamespace = "PaymentAuthorization.Application";
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    [Fact]
    public void Domain_depends_on_nothing_but_the_language_core()
    {
        var result = Types.InAssembly(typeof(Domain.Money).Assembly)
            .That().ResideInNamespace(DomainNamespace)
            .Should().NotHaveDependencyOnAny(ApplicationNamespace, InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_does_not_depend_on_infrastructure()
    {
        var result = Types.InAssembly(typeof(Application.AuthorizePayment).Assembly)
            .That().ResideInNamespace(ApplicationNamespace)
            .Should().NotHaveDependencyOnAny(InfrastructureNamespace)
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    [Fact]
    public void Application_depends_only_on_application_domain_and_the_language_core()
    {
        var result = Types.InAssembly(typeof(Application.AuthorizePayment).Assembly)
            .That().ResideInNamespace(ApplicationNamespace)
            .Should().OnlyHaveDependenciesOn(
                ApplicationNamespace,
                DomainNamespace,
                "System",
                "Microsoft")
            .GetResult();

        Assert.True(result.IsSuccessful, Describe(result));
    }

    private static string Describe(TestResult result) =>
        result.IsSuccessful
            ? string.Empty
            : "Violations: " + string.Join(", ", result.FailingTypeNames ?? []);
}

